function dashboardQuery(selector) {
    return document.querySelector(selector);
}

function dashboardQueryAll(selector) {
    if (typeof document === "undefined" || typeof document.querySelectorAll !== "function") return [];
    return document.querySelectorAll(selector);
}

function qsaseRouteKey(route = QSASE_DEFAULT_ROUTE) {
    return `${route.moduleId}/${route.viewId}`;
}

function qsaseNavigationModule(moduleId) {
    return QSASE_DASHBOARD_NAVIGATION.find((module) => module.id === moduleId) || QSASE_DASHBOARD_NAVIGATION[0];
}

function qsaseNavigationView(moduleId, viewId) {
    if (moduleId === QSASE_TEAM_ROUTE.moduleId && viewId === QSASE_TEAM_ROUTE.viewId) {
        return { id: QSASE_TEAM_ROUTE.viewId, label: QSASE_TEAM_ROUTE.label };
    }
    const module = qsaseNavigationModule(moduleId);
    return module.views.find((view) => view.id === viewId) || module.views[0];
}

function qsaseDashboardRouteCandidate(search = "") {
    const raw = String(search || "").replace(/^\?/, "");
    const params = raw.split("&").reduce((output, pair) => {
        const [key, value = ""] = pair.split("=");
        if (!key) return output;
        output[decodeURIComponent(key)] = decodeURIComponent(value.replace(/\+/g, " "));
        return output;
    }, {});
    return `${params.module || ""}/${params.view || ""}`;
}

function qsaseRouteDisplayLabel(route = QSASE_DEFAULT_ROUTE) {
    if (qsaseRouteKey(route) === qsaseRouteKey(QSASE_TEAM_ROUTE)) return QSASE_TEAM_ROUTE.label;
    if (qsaseRouteKey(route) === qsaseRouteKey(QSASE_SYSTEM_ROUTE)) return QSASE_SYSTEM_ROUTE.label;
    const module = qsaseNavigationModule(route.moduleId);
    const view = qsaseNavigationView(route.moduleId, route.viewId);
    return `${module.label} · ${view.label}`;
}

function resolveQsaseDashboardRoute(search = "") {
    const candidate = qsaseDashboardRouteCandidate(search);
    if (candidate === "fund/holdings") return QSASE_ROUTE_INDEX.get("fund/portfolio") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "trade/lifecycle") return QSASE_ROUTE_INDEX.get("trade/orders") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "decide/intents") return QSASE_ROUTE_INDEX.get("decide/decision") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "learn/replay") return QSASE_ROUTE_INDEX.get("learn/improvements") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "learn/briefs") return QSASE_ROUTE_INDEX.get("learn/outcomes") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "system/activity") return QSASE_ROUTE_INDEX.get("system/overview") || { ...QSASE_DEFAULT_ROUTE };
    if (candidate === "system/health") return QSASE_ROUTE_INDEX.get("system/overview") || { ...QSASE_DEFAULT_ROUTE };
    return QSASE_ROUTE_INDEX.get(candidate) || { ...QSASE_DEFAULT_ROUTE };
}

function currentQsaseDashboardRoute() {
    const moduleId = document.documentElement?.dataset.qsaseModule;
    const viewId = document.documentElement?.dataset.qsaseView;
    const candidate = `${moduleId || ""}/${viewId || ""}`;
    if (QSASE_ROUTE_INDEX.has(candidate)) return { moduleId, viewId };
    return resolveQsaseDashboardRoute(typeof window !== "undefined" ? window.location?.search : "");
}

function qsaseDashboardRouteHref(moduleId, viewId) {
    const route = QSASE_ROUTE_INDEX.get(`${moduleId}/${viewId}`) || QSASE_DEFAULT_ROUTE;
    return `/dashboard/?module=${encodeURIComponent(route.moduleId)}&view=${encodeURIComponent(route.viewId)}`;
}

function qsaseLifecycleFallbackContext(routeKey) {
    const fallback = QSASE_LIFECYCLE_FALLBACK_ROUTE_CONTEXTS[routeKey]
        || ["unrelated", [], [], [], "Lifecycle relationship unavailable", "This page has not been mapped to the canonical lifecycle."];
    const [relationship, primary, supporting, outcome, relationshipLabel, moduleRelationship] = fallback;
    return {
        relationship,
        primary_stage_ids: primary,
        supporting_stage_ids: supporting,
        outcome_stage_ids: outcome,
        cross_cutting: relationship === "cross_cutting",
        relationship_label: relationshipLabel,
        module_relationship: moduleRelationship,
        entry_from: [],
        hands_off_to: []
    };
}

function qsaseLifecycleModel(qsase = {}) {
    const canonical = qsase.end_to_end_lifecycle || qsase.operator_dashboard?.end_to_end_lifecycle || {};
    const stages = asArray(canonical.stages);
    const routeContexts = canonical.route_contexts || {};
    if (stages.length === 10 && Object.keys(routeContexts).length) return canonical;
    return {
        artifact_type: "qadam_lifecycle_frontend_unavailable_fallback",
        status: "lifecycle_runtime_unavailable",
        generated_at: null,
        stage_count: 10,
        single_global_current_stage: false,
        concurrent_item_lifecycles_supported: true,
        stages: QSASE_LIFECYCLE_FALLBACK_STAGES,
        route_contexts: Object.fromEntries(
            Object.keys(QSASE_LIFECYCLE_FALLBACK_ROUTE_CONTEXTS).map((routeKey) => [routeKey, qsaseLifecycleFallbackContext(routeKey)])
        ),
        stage_states: Object.fromEntries(QSASE_LIFECYCLE_FALLBACK_STAGES.map((stage) => [stage.stage_id, {
            stage_id: stage.stage_id,
            state: "unavailable",
            summary: "Current stage activity is unavailable; the structural lifecycle remains visible.",
            item_count: 0,
            blockers: ["Refresh the canonical lifecycle projection."],
            freshness: "unavailable",
            source_generated_at: null,
            artifact_refs: []
        }]))
    };
}

function qsaseLifecycleStageRelation(context = {}, stageId = "") {
    if (context.cross_cutting === true) return "cross_cutting";
    if (asArray(context.primary_stage_ids).includes(stageId)) return "primary";
    if (asArray(context.outcome_stage_ids).includes(stageId)) return "outcome_mirror";
    if (asArray(context.supporting_stage_ids).includes(stageId)) return "supporting";
    return "unrelated";
}

function qsaseLifecycleStateLabel(value = "unavailable") {
    const labels = {
        active: "Active now",
        waiting_for_evidence: "Waiting for evidence",
        blocked: "Cannot advance",
        idle: "No current item",
        degraded: "Needs attention",
        unavailable: "Status unavailable"
    };
    return labels[value] || qsaseHumanText(value, "Status unavailable");
}

function qsaseLifecycleRelationshipClass(value = "unrelated") {
    return `is-${String(value || "unrelated").replaceAll("_", "-")}`;
}

function qsaseLifecycleRuntimeClass(value = "unavailable") {
    if (value === "active") return "runtime-active";
    if (value === "waiting_for_evidence" || value === "idle") return "runtime-waiting";
    if (value === "blocked") return "runtime-blocked";
    return "runtime-degraded";
}

function qsaseLifecycleStageDestination(stage = {}) {
    const routeKey = asArray(stage.primary_routes)[0];
    if (!routeKey || !QSASE_ROUTE_INDEX.has(routeKey)) return null;
    return QSASE_ROUTE_INDEX.get(routeKey);
}

function renderQadamLifecycleTimeline(qsase = {}, activeRoute = QSASE_DEFAULT_ROUTE) {
    const model = qsaseLifecycleModel(qsase);
    const routeKey = qsaseRouteKey(activeRoute);
    const context = model.route_contexts?.[routeKey] || qsaseLifecycleFallbackContext(routeKey);
    const stages = asArray(model.stages).slice(0, 10);
    const sourceLabel = model.artifact_type === "qadam_lifecycle_frontend_unavailable_fallback"
        ? "Live stage state unavailable"
        : model.generated_at
            ? `Updated ${formatTime(model.generated_at)}`
            : "Canonical lifecycle";
    return `
        <section class="qadam-lifecycle ${context.cross_cutting ? "is-cross-cutting" : ""}" data-qadam-lifecycle data-lifecycle-route="${literalHtmlText(routeKey)}" data-lifecycle-relationship="${literalHtmlText(context.relationship || "unrelated")}" aria-labelledby="qadam-lifecycle-title-${literalHtmlText(routeKey.replace("/", "-"))}">
            <header class="qadam-lifecycle-header">
                <div>
                    <span>How this page fits Qadam</span>
                    <h2 id="qadam-lifecycle-title-${literalHtmlText(routeKey.replace("/", "-"))}">${qsaseHtmlText(context.relationship_label || "Lifecycle relationship unavailable")}</h2>
                    <p>${qsaseHtmlText(context.module_relationship || "This module is not yet mapped to the lifecycle.")}</p>
                </div>
                <div class="qadam-lifecycle-source">
                    <strong>10-stage lifecycle</strong>
                    <span>${qsaseHtmlText(sourceLabel)}</span>
                </div>
            </header>
            <ol class="qadam-lifecycle-track" aria-label="Qadam's ten-stage operating lifecycle">
                ${stages.map((stage, index) => {
                    const stageId = stage.stage_id || `stage-${index + 1}`;
                    const runtime = model.stage_states?.[stageId] || {
                        state: "unavailable",
                        summary: "Current stage activity is unavailable.",
                        blockers: [],
                        freshness: "unavailable",
                        artifact_refs: []
                    };
                    const relation = qsaseLifecycleStageRelation(context, stageId);
                    const tooltipId = `qadam-lifecycle-${routeKey.replace(/[^a-z0-9]+/gi, "-")}-${stageId}`;
                    const destination = qsaseLifecycleStageDestination(stage);
                    const blockers = asArray(runtime.blockers);
                    const inputs = asArray(stage.inputs);
                    const outputs = asArray(stage.outputs);
                    const actors = asArray(stage.actors);
                    const subStages = asArray(stage.sub_stages);
                    return `
                        <li class="qadam-lifecycle-stage ${qsaseLifecycleRelationshipClass(relation)} ${qsaseLifecycleRuntimeClass(runtime.state)} ${index < 5 ? "is-first-half" : "is-second-half"}" data-lifecycle-stage="${literalHtmlText(stageId)}" data-lifecycle-relation="${literalHtmlText(relation)}" data-lifecycle-runtime="${literalHtmlText(runtime.state || "unavailable")}">
                            <button class="qadam-lifecycle-trigger" type="button" data-qadam-lifecycle-trigger aria-expanded="false" aria-controls="${literalHtmlText(tooltipId)}" aria-describedby="${literalHtmlText(tooltipId)}" aria-label="Stage ${qsaseHtmlText(stage.number || index + 1)}: ${qsaseHtmlText(stage.label)}. ${qsaseLifecycleStateLabel(runtime.state)}">
                                <span>${String(stage.number || index + 1).padStart(2, "0")}</span>
                                <strong>${qsaseHtmlText(stage.short_label || stage.label)}</strong>
                                <small><i aria-hidden="true"></i>${qsaseHtmlText(qsaseLifecycleStateLabel(runtime.state))}</small>
                            </button>
                            <div id="${literalHtmlText(tooltipId)}" class="qadam-lifecycle-tooltip" role="tooltip" data-qadam-lifecycle-tooltip>
                                <header>
                                    <span>Stage ${qsaseHtmlText(stage.number || index + 1)} of 10</span>
                                    <strong>${qsaseHtmlText(stage.label)}</strong>
                                </header>
                                <p>${qsaseHtmlText(stage.plain_english)}</p>
                                <dl>
                                    <div><dt>Question</dt><dd>${qsaseHtmlText(stage.key_question)}</dd></div>
                                    <div><dt>Current state</dt><dd>${qsaseHtmlText(runtime.summary || qsaseLifecycleStateLabel(runtime.state))}</dd></div>
                                    <div><dt>This page</dt><dd>${qsaseHtmlText(relation === "primary" ? "Explains this stage" : relation === "supporting" ? "Supplies evidence to this stage" : relation === "outcome_mirror" ? "Shows an outcome from this stage" : relation === "cross_cutting" ? "Contributes across this stage" : "Provides wider context")}</dd></div>
                                </dl>
                                <div class="qadam-lifecycle-tooltip-grid">
                                    <section><span>Inside this stage</span><ul>${subStages.map((item) => `<li>${qsaseHtmlText(item)}</li>`).join("")}</ul></section>
                                    <section><span>Handoff</span><p><b>Receives:</b> ${qsaseHtmlText(inputs.join("; ") || "Previous-stage evidence")}</p><p><b>Produces:</b> ${qsaseHtmlText(outputs.join("; ") || "Next-stage evidence")}</p></section>
                                </div>
                                <p class="qadam-lifecycle-actors"><b>Team:</b> ${qsaseHtmlText(actors.join(", ") || "Qadam operating team")}</p>
                                ${blockers.length ? `<p class="qadam-lifecycle-blocker"><b>Why it cannot advance:</b> ${qsaseHtmlText(blockers[0])}</p>` : ""}
                                <p class="qadam-lifecycle-boundary">${qsaseHtmlText(stage.safety_boundary || "Public dashboard information only.")}</p>
                                ${destination ? `<a href="${qsaseDashboardRouteHref(destination.moduleId, destination.viewId)}" data-qsase-route data-qsase-module-target="${literalHtmlText(destination.moduleId)}" data-qsase-view-target="${literalHtmlText(destination.viewId)}">View this stage <span aria-hidden="true">&rarr;</span></a>` : ""}
                            </div>
                        </li>
                    `;
                }).join("")}
            </ol>
            <p class="qadam-lifecycle-concurrency">Qadam can have different research ideas, paper orders, and lessons in several stages at once. The highlighted stage shows this page's role, not one global system position.</p>
        </section>
    `;
}

function qsaseSetSidebarOpen(open) {
    const shell = dashboardQuery("[data-qsase-navigation-shell]");
    if (!shell) return;
    const nextOpen = Boolean(open);
    shell.classList.toggle("is-sidebar-open", nextOpen);
    document.body?.classList.toggle("qsase-sidebar-lock", nextOpen);
    dashboardQueryAll("[data-qsase-sidebar-toggle]").forEach((button) => {
        button.setAttribute("aria-expanded", nextOpen ? "true" : "false");
    });
}

function bindQsaseRouteLinks(root = document) {
    if (!root?.querySelectorAll) return;
    root.querySelectorAll("[data-qsase-route]").forEach((link) => {
        if (link.dataset.qsaseRouteBound === "true") return;
        link.dataset.qsaseRouteBound = "true";
        link.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            navigateQsaseDashboard(link.dataset.qsaseModuleTarget, link.dataset.qsaseViewTarget);
        });
    });
}

function closeQsaseLifecycleDisclosures(root = document, returnFocus = false) {
    if (!root?.querySelectorAll) return;
    root.querySelectorAll("[data-qadam-lifecycle-trigger][aria-expanded='true']").forEach((trigger) => {
        trigger.setAttribute("aria-expanded", "false");
        trigger.closest?.("[data-lifecycle-stage]")?.classList.remove("is-open");
        if (returnFocus && typeof trigger.focus === "function") trigger.focus();
    });
}

function initQsaseLifecycleDisclosures(root = document) {
    if (!root?.querySelectorAll) return;
    root.querySelectorAll("[data-qadam-lifecycle-trigger]").forEach((trigger) => {
        if (trigger.dataset.qadamLifecycleBound === "true") return;
        trigger.dataset.qadamLifecycleBound = "true";
        trigger.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            const stage = trigger.closest?.("[data-lifecycle-stage]");
            stage?.classList.remove("suppress-preview");
            const shouldOpen = trigger.getAttribute("aria-expanded") !== "true";
            closeQsaseLifecycleDisclosures(root);
            trigger.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
            stage?.classList.toggle("is-open", shouldOpen);
        });
        trigger.addEventListener("keydown", (event) => {
            if (event.key !== "Escape") return;
            event.preventDefault();
            trigger.closest?.("[data-lifecycle-stage]")?.classList.add("suppress-preview");
            closeQsaseLifecycleDisclosures(root, true);
        });
        const stage = trigger.closest?.("[data-lifecycle-stage]");
        if (stage && stage.dataset.qadamLifecyclePreviewBound !== "true") {
            stage.dataset.qadamLifecyclePreviewBound = "true";
            stage.addEventListener("pointerleave", () => stage.classList.remove("suppress-preview"));
            stage.addEventListener("focusout", (event) => {
                if (!stage.contains(event.relatedTarget)) stage.classList.remove("suppress-preview");
            });
        }
    });
    if (root.dataset && root.dataset.qadamLifecycleOutsideBound !== "true" && typeof root.addEventListener === "function") {
        root.dataset.qadamLifecycleOutsideBound = "true";
        root.addEventListener("click", (event) => {
            if (!event.target?.closest?.("[data-lifecycle-stage]")) closeQsaseLifecycleDisclosures(root);
        });
    }
}

function syncQsaseModuleNavigation(route = currentQsaseDashboardRoute(), options = {}) {
    const resolved = QSASE_ROUTE_INDEX.get(qsaseRouteKey(route)) || QSASE_DEFAULT_ROUTE;
    const module = qsaseNavigationModule(resolved.moduleId);
    const view = qsaseNavigationView(resolved.moduleId, resolved.viewId);
    bindQsaseRouteLinks();
    if (document.documentElement) {
        document.documentElement.dataset.qsaseModule = resolved.moduleId;
        document.documentElement.dataset.qsaseView = resolved.viewId;
    }
    dashboardQueryAll("[data-qsase-module-panel]").forEach((panel) => {
        const active = panel.dataset.qsaseModulePanel === resolved.moduleId
            && panel.dataset.qsaseViewPanel === resolved.viewId;
        panel.hidden = !active;
        panel.setAttribute("aria-hidden", active ? "false" : "true");
    });
    dashboardQueryAll("[data-qsase-nav-route]").forEach((link) => {
        const active = link.dataset.qsaseModuleTarget === resolved.moduleId
            && link.dataset.qsaseViewTarget === resolved.viewId;
        link.classList.toggle("active", active);
        if (active) link.setAttribute("aria-current", "page");
        else link.removeAttribute("aria-current");
    });
    dashboardQueryAll("[data-qsase-nav-group]").forEach((group) => {
        const teamRoute = qsaseRouteKey(resolved) === qsaseRouteKey(QSASE_TEAM_ROUTE);
        group.classList.toggle("active", !teamRoute && group.dataset.qsaseNavGroup === resolved.moduleId);
    });
    const current = dashboardQuery("[data-qsase-current-view]");
    if (current) current.textContent = qsaseRouteDisplayLabel(resolved);
    if (typeof document !== "undefined") document.title = `${view.label} | Qadam Dashboard`;
    if (typeof window !== "undefined" && window.history?.replaceState) {
        const browserCandidate = qsaseDashboardRouteCandidate(window.location?.search || "");
        const legacyAlias = [
            "fund/holdings",
            "trade/lifecycle",
            "decide/intents",
            "system/activity",
            "system/health"
        ].includes(browserCandidate);
        if (legacyAlias) {
            window.history.replaceState(
                { qadamView: qsaseRouteKey(resolved) },
                "",
                qsaseDashboardRouteHref(resolved.moduleId, resolved.viewId)
            );
        }
    }
    if (options.closeSidebar !== false) qsaseSetSidebarOpen(false);
    if (options.scroll !== false && typeof window !== "undefined" && typeof window.scrollTo === "function") {
        window.scrollTo({ top: 0, behavior: "auto" });
    }
    if (typeof window !== "undefined" && typeof window.dispatchEvent === "function") {
        window.dispatchEvent(new CustomEvent("qadam-dashboard-route-change", {
            detail: { moduleId: resolved.moduleId, viewId: resolved.viewId }
        }));
    }
    return resolved;
}

function navigateQsaseDashboard(moduleId, viewId, options = {}) {
    const route = QSASE_ROUTE_INDEX.get(`${moduleId}/${viewId}`) || QSASE_DEFAULT_ROUTE;
    if (typeof window !== "undefined" && window.history?.pushState && options.history !== false) {
        window.history.pushState({ qadamView: qsaseRouteKey(route) }, "", qsaseDashboardRouteHref(route.moduleId, route.viewId));
    }
    return syncQsaseModuleNavigation(route, { scroll: options.scroll !== false });
}

function selectQsaseAllocationMode(button) {
    const root = button?.closest?.("[data-qsase-allocation]");
    const mode = button?.dataset?.qsaseAllocationMode;
    if (!root || !mode) return;
    root.querySelectorAll("[data-qsase-allocation-mode]").forEach((control) => {
        control.setAttribute("aria-selected", control.dataset.qsaseAllocationMode === mode ? "true" : "false");
    });
    root.querySelectorAll("[data-qsase-allocation-panel]").forEach((panel) => {
        const active = panel.dataset.qsaseAllocationPanel === mode;
        panel.hidden = !active;
        panel.setAttribute("aria-hidden", active ? "false" : "true");
    });
}

function initQsaseModuleNavigation() {
    if (qsaseModuleNavigationInitialized || typeof document === "undefined" || typeof document.addEventListener !== "function") return;
    qsaseModuleNavigationInitialized = true;
    document.addEventListener("click", (event) => {
        const allocationMode = event.target?.closest?.("[data-qsase-allocation-mode]");
        if (allocationMode) {
            selectQsaseAllocationMode(allocationMode);
            return;
        }
        if (event.target?.closest?.("[data-qsase-sidebar-toggle]")) {
            const shell = dashboardQuery("[data-qsase-navigation-shell]");
            qsaseSetSidebarOpen(!shell?.classList.contains("is-sidebar-open"));
            return;
        }
        if (event.target?.closest?.("[data-qsase-sidebar-close]")) qsaseSetSidebarOpen(false);
    });
    if (typeof window !== "undefined" && window.addEventListener) {
        window.addEventListener("popstate", () => syncQsaseModuleNavigation(resolveQsaseDashboardRoute(window.location?.search), { scroll: false }));
        window.addEventListener("keydown", (event) => {
            if (event?.key === "Escape") {
                qsaseSetSidebarOpen(false);
                closeQsaseLifecycleDisclosures(document, true);
            }
        });
    }
}

function readDashboardViewScrollState() {
    try {
        if (typeof sessionStorage === "undefined") return {};
        return JSON.parse(sessionStorage.getItem(DASHBOARD_VIEW_SCROLL_KEY) || "{}");
    } catch (_error) {
        return {};
    }
}

function writeDashboardViewScrollState(state) {
    try {
        if (typeof sessionStorage !== "undefined") {
            sessionStorage.setItem(DASHBOARD_VIEW_SCROLL_KEY, JSON.stringify(state));
        }
    } catch (_error) {
        // Scroll restoration is a convenience; view switching should still work.
    }
}

function dashboardViewLabel(viewId) {
    return DASHBOARD_VIEWS.find((view) => view.id === viewId)?.label || "Overview";
}

function currentDashboardView() {
    return document.documentElement?.dataset.dashboardActiveView || "overview";
}

function readDashboardDebugPreference() {
    if (typeof window === "undefined" || !window.localStorage) return false;
    try {
        return window.localStorage.getItem(DASHBOARD_ADVANCED_DEBUG_KEY) === "on";
    } catch (_error) {
        return false;
    }
}

function writeDashboardDebugPreference(enabled) {
    if (typeof window === "undefined" || !window.localStorage) return;
    try {
        window.localStorage.setItem(DASHBOARD_ADVANCED_DEBUG_KEY, enabled ? "on" : "off");
    } catch (_error) {
        // Preference storage is optional; the in-page mode still updates.
    }
}

function dashboardDebugModeEnabled() {
    return document.documentElement?.dataset.dashboardDebug === "on";
}

function resolveDashboardHash(hash = "") {
    const target = String(hash || "").replace(/^#/, "");
    if (!target) return { viewId: "overview", targetId: "mission-control", legacy: false };
    if (DASHBOARD_VIEW_IDS.has(target)) return { viewId: target, targetId: null, legacy: false };
    if (DASHBOARD_LEGACY_HASH_TARGETS[target]) {
        return { ...DASHBOARD_LEGACY_HASH_TARGETS[target], legacy: true };
    }
    return { viewId: "overview", targetId: "mission-control", legacy: false };
}

function setDashboardViewSectionVisibility(viewId) {
    if (typeof document.querySelectorAll !== "function") return;
    const debugEnabled = dashboardDebugModeEnabled();
    document.querySelectorAll("[data-dashboard-view-section]").forEach((section) => {
        const debugOnly = section.hasAttribute("data-dashboard-debug-only");
        const active = section.dataset.dashboardViewSection === viewId && (!debugOnly || debugEnabled);
        section.hidden = !active;
        section.setAttribute("aria-hidden", active ? "false" : "true");
    });
    document.querySelectorAll("[data-dashboard-debug-only]:not([data-dashboard-view-section])").forEach((section) => {
        section.hidden = !debugEnabled;
        section.setAttribute("aria-hidden", debugEnabled ? "false" : "true");
    });
}

function setDashboardViewNavigationState(viewId) {
    if (typeof document.querySelectorAll !== "function") return;
    const current = dashboardQuery("[data-dashboard-view-current]") || dashboardQuery("[data-cockpit-nav-current]");
    document.querySelectorAll("[data-dashboard-view-link]").forEach((link) => {
        const active = link.dataset.dashboardViewTarget === viewId;
        link.classList.toggle("active", active);
        if (active) {
            link.setAttribute("aria-current", "page");
            if (current) current.textContent = link.textContent || dashboardViewLabel(viewId);
        } else {
            link.removeAttribute("aria-current");
        }
    });
}

function setDashboardDebugControls(enabled) {
    if (typeof document.querySelectorAll !== "function") return;
    document.querySelectorAll("[data-dashboard-debug-toggle]").forEach((button) => {
        button.setAttribute("aria-pressed", enabled ? "true" : "false");
        button.setAttribute("aria-expanded", enabled ? "true" : "false");
        button.setAttribute("aria-label", enabled ? "Hide advanced sections" : "Show advanced sections");
        button.classList.toggle("active", enabled);
        button.textContent = enabled ? "Hide advanced" : "Advanced";
    });
    document.querySelectorAll("[data-dashboard-advanced-links]").forEach((links) => {
        links.hidden = !enabled;
        links.setAttribute("aria-hidden", enabled ? "false" : "true");
        links.setAttribute("role", "region");
        links.setAttribute("aria-label", "Diagnostics navigation");
    });
}

function setDashboardDebugMode(enabled, options = {}) {
    const nextEnabled = Boolean(enabled);
    if (document.documentElement) {
        document.documentElement.dataset.dashboardDebug = nextEnabled ? "on" : "off";
    }
    setDashboardDebugControls(nextEnabled);
    if (options.persist !== false) writeDashboardDebugPreference(nextEnabled);
    setDashboardViewSectionVisibility(currentDashboardView());
}

function storeDashboardViewScrollPosition(viewId) {
    if (typeof window === "undefined") return;
    const state = readDashboardViewScrollState();
    state[viewId] = Math.max(0, Math.round(Number(window.scrollY || 0)));
    writeDashboardViewScrollState(state);
}

function dashboardStickyScrollOffset() {
    if (typeof document === "undefined") return 0;
    const stickySelectors = [".cockpit-nav", "[data-dashboard-safety-strip]"];
    const measuredOffset = stickySelectors.reduce((offset, selector) => {
        const node = document.querySelector?.(selector);
        if (!node || typeof node.getBoundingClientRect !== "function") return offset;
        const styles = typeof window !== "undefined" && window.getComputedStyle
            ? window.getComputedStyle(node)
            : null;
        if (styles && styles.display === "none") return offset;
        const rect = node.getBoundingClientRect();
        return Math.max(offset, rect.bottom || 0);
    }, 0) + 12;
    const estimatedStickyStack = typeof window !== "undefined" && window.innerWidth < 700 ? 260 : 220;
    return Math.max(measuredOffset, estimatedStickyStack);
}

function scrollDashboardTargetIntoView(target) {
    if (!target || typeof window === "undefined") return false;
    if (typeof target.getBoundingClientRect === "function" && typeof window.scrollTo === "function") {
        const top = Math.max(0, (window.scrollY || 0) + target.getBoundingClientRect().top - dashboardStickyScrollOffset());
        window.scrollTo({ top, behavior: "auto" });
        return true;
    }
    if (target.scrollIntoView) {
        target.scrollIntoView({ block: "start" });
        return true;
    }
    return false;
}

function restoreDashboardViewScrollPosition(viewId, targetId, shouldScroll) {
    if (!shouldScroll || typeof window === "undefined") return;
    const restore = () => {
        const target = targetId && typeof document.getElementById === "function"
            ? document.getElementById(targetId)
            : null;
        if (scrollDashboardTargetIntoView(target)) {
            return;
        }
        const state = readDashboardViewScrollState();
        if (typeof window.scrollTo === "function") {
            window.scrollTo({ top: state[viewId] || 0, behavior: "auto" });
        }
    };
    if (typeof window.requestAnimationFrame === "function") {
        window.requestAnimationFrame(restore);
    } else {
        restore();
    }
}

function activateDashboardView(viewId, options = {}) {
    const resolved = DASHBOARD_VIEW_IDS.has(viewId) ? viewId : "overview";
    if (resolved !== "overview" && !dashboardDebugModeEnabled()) {
        setDashboardDebugMode(true, { persist: options.persistDebug !== false, scroll: false });
    }
    const previous = currentDashboardView();
    if (previous !== resolved) storeDashboardViewScrollPosition(previous);
    if (document.documentElement) {
        document.documentElement.dataset.dashboardActiveView = resolved;
    }
    setDashboardViewSectionVisibility(resolved);
    setDashboardViewNavigationState(resolved);
    restoreDashboardViewScrollPosition(resolved, options.targetId, options.scroll !== false);
    return resolved;
}

function activateDashboardViewFromHash(hash, options = {}) {
    const resolved = resolveDashboardHash(hash);
    return activateDashboardView(resolved.viewId, {
        targetId: resolved.targetId,
        scroll: options.scroll
    });
}

function initCockpitNavigation() {
    if (typeof document.querySelectorAll !== "function") return;
    const links = Array.from(document.querySelectorAll("[data-dashboard-view-link]"));
    if (!links.length) return;
    const initialHash = typeof window !== "undefined" ? window.location?.hash || "" : "";
    const initialResolved = resolveDashboardHash(initialHash);
    setDashboardDebugMode(readDashboardDebugPreference() || initialResolved.viewId !== "overview", {
        persist: false,
        scroll: false
    });

    links.forEach((link) => {
        link.addEventListener("click", (event) => {
            const viewId = link.dataset.dashboardViewTarget || "overview";
            if (!DASHBOARD_VIEW_IDS.has(viewId)) return;
            event?.preventDefault?.();
            if (typeof window !== "undefined" && window.history?.pushState) {
                window.history.pushState(null, "", `#${viewId}`);
            }
            activateDashboardView(viewId);
        });

        link.addEventListener("keydown", (event) => {
            const key = event?.key;
            if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(key)) return;
            event.preventDefault();
            const currentIndex = links.indexOf(link);
            let nextIndex = currentIndex;
            if (key === "ArrowLeft") nextIndex = Math.max(0, currentIndex - 1);
            if (key === "ArrowRight") nextIndex = Math.min(links.length - 1, currentIndex + 1);
            if (key === "Home") nextIndex = 0;
            if (key === "End") nextIndex = links.length - 1;
            links[nextIndex]?.focus?.();
        });
    });

    document.querySelectorAll("[data-dashboard-debug-toggle]").forEach((button) => {
        button.addEventListener("click", () => {
            setDashboardDebugMode(!dashboardDebugModeEnabled(), { persist: true, scroll: true });
        });
    });

    activateDashboardViewFromHash(initialHash, { scroll: false });

    if (typeof window !== "undefined" && window.addEventListener) {
        window.addEventListener("hashchange", () => {
            activateDashboardViewFromHash(window.location?.hash || "", { scroll: true });
        });
        window.addEventListener("popstate", () => {
            activateDashboardViewFromHash(window.location?.hash || "", { scroll: true });
        });
        window.addEventListener("keydown", (event) => {
            if (event?.key !== "Escape" || !dashboardDebugModeEnabled()) return;
            setDashboardDebugMode(false, { persist: true, scroll: false });
            document.querySelector("[data-dashboard-debug-toggle]")?.focus?.();
        });
    }
}

function clampDashboardTooltipValue(value, min, max) {
    if (!Number.isFinite(value)) return min;
    if (!Number.isFinite(max) || max < min) return min;
    return Math.min(Math.max(value, min), max);
}

function isDashboardGuideTooltipActive(marker) {
    if (!marker) return false;
    const active = typeof document !== "undefined" ? document.activeElement : null;
    return Boolean(
        (typeof marker.matches === "function" && marker.matches(":hover")) ||
        (active && typeof marker.contains === "function" && marker.contains(active))
    );
}

function positionDashboardGuideTooltip(marker) {
    if (!marker || typeof window === "undefined") return;
    const button = marker.querySelector?.(".info-button");
    const card = marker.querySelector?.('[data-tooltip-contract="nontechnical-guide"]');
    if (!button || !card || typeof button.getBoundingClientRect !== "function") return;

    const viewportWidth = Math.max(document.documentElement?.clientWidth || 0, window.innerWidth || 0);
    const viewportHeight = Math.max(document.documentElement?.clientHeight || 0, window.innerHeight || 0);
    if (!viewportWidth || !viewportHeight) return;

    const gutter = 16;
    const gap = 10;
    const cardWidth = Math.min(384, Math.max(220, viewportWidth - (gutter * 2)));
    card.style.setProperty("--qadam-tooltip-width", `${cardWidth}px`);

    const buttonRect = button.getBoundingClientRect();
    const cardRect = card.getBoundingClientRect();
    const measuredHeight = Math.min(cardRect.height || 240, viewportHeight - (gutter * 2));
    const maxLeft = viewportWidth - cardWidth - gutter;
    const centeredLeft = buttonRect.left + (buttonRect.width / 2) - (cardWidth / 2);
    const left = clampDashboardTooltipValue(centeredLeft, gutter, maxLeft);

    let top = buttonRect.bottom + gap;
    let placement = "bottom";
    if (top + measuredHeight > viewportHeight - gutter) {
        top = buttonRect.top - measuredHeight - gap;
        placement = "top";
    }
    top = clampDashboardTooltipValue(top, gutter, viewportHeight - measuredHeight - gutter);

    card.style.setProperty("--qadam-tooltip-left", `${Math.round(left)}px`);
    card.style.setProperty("--qadam-tooltip-top", `${Math.round(top)}px`);
    marker.dataset.guideTooltipPlacement = placement;
}

function refreshDashboardGuideTooltipPositions() {
    if (typeof document === "undefined") return;
    document.querySelectorAll(".qsase-guide-marker[data-guide-tooltip-bound='true']").forEach((marker) => {
        if (isDashboardGuideTooltipActive(marker)) positionDashboardGuideTooltip(marker);
    });
}

function initDashboardGuideTooltips() {
    if (typeof document === "undefined" || typeof document.querySelectorAll !== "function") return;
    if (typeof window === "undefined") return;
    document.querySelectorAll(".qsase-guide-marker").forEach((marker) => {
        const card = marker.querySelector?.('[data-tooltip-contract="nontechnical-guide"]');
        if (!card || marker.dataset.guideTooltipBound === "true") return;
        marker.dataset.guideTooltipBound = "true";
        marker.addEventListener("mouseenter", () => positionDashboardGuideTooltip(marker));
        marker.addEventListener("focusin", () => positionDashboardGuideTooltip(marker));
        marker.addEventListener("touchstart", () => positionDashboardGuideTooltip(marker), { passive: true });
    });
    if (window.qadamDashboardGuideTooltipListenersBound) return;
    window.qadamDashboardGuideTooltipListenersBound = true;
    window.addEventListener("resize", refreshDashboardGuideTooltipPositions, { passive: true });
    window.addEventListener("scroll", refreshDashboardGuideTooltipPositions, { passive: true, capture: true });
}

function dashboardText(value, fallback = "Not connected yet") {
    if (value === null || value === undefined || value === "") return fallback;
    return String(value)
        .replace(/\bPhase\s*7\b/gi, "60-day paper growth trial")
        .replace(/\bQ7-15\b/g, "Paper Growth Trial")
        .replace(/\bQ7-16\b/g, "Growth Review")
        .replace(/\bQ7\b/g, "Paper Growth Trial")
        .replace(/phase7[_ -]?demo[_ -]?proof/gi, "paper growth trial")
        .replace(/phase7[_ -]?proof/gi, "paper growth proof")
        .replace(/\bphase7\b/gi, "paper growth")
        .replace(/30[- ]day demo[- ]proof/gi, "60-day paper growth")
        .replace(/30 consecutive calendar day/gi, "60-day paper growth")
        .replace(/100[- ]trade maturity/gi, "2x portfolio target")
        .replaceAll("_", " ");
}

function normalizeCanonicalStatusToken(value) {
    return String(value || "")
        .replaceAll("_", " ")
        .replaceAll("-", " ")
        .replace(/\s+/g, " ")
        .trim()
        .toLowerCase();
}

function canonicalStatusRecord(value, options = {}) {
    const token = normalizeCanonicalStatusToken(dashboardText(value, options.fallback || "not exported"));
    const exact = CANONICAL_STATUS_BY_TOKEN[token];
    if (exact) return exact;
    if (options.strict) return null;
    if (/ui inferred|display inferred|unsafe|failed|failure|error|fault|write enabled|live capital enabled/.test(token)) return { key: "fault", ...CANONICAL_STATUS_LANGUAGE.fault };
    if (/blocked|hard block|kill switch|no submit|disabled contract|live blocked/.test(token)) return { key: "safety-stop", ...CANONICAL_STATUS_LANGUAGE["safety-stop"] };
    if (/missing|not exported|not connected|credential|unavailable/.test(token)) return { key: "missing-setup", ...CANONICAL_STATUS_LANGUAGE["missing-setup"] };
    if (/degraded|stale|fallback|partial|weak/.test(token)) return { key: "degraded", ...CANONICAL_STATUS_LANGUAGE.degraded };
    if (/optional|not required|supplemental only|ready to build|fallback only|receiver pending|disabled live mode|live mcp disabled/.test(token)) return { key: "optional", ...CANONICAL_STATUS_LANGUAGE.optional };
    if (/pending|waiting|deferred|not ready|not run|planned/.test(token)) return { key: "waiting-for-evidence", ...CANONICAL_STATUS_LANGUAGE["waiting-for-evidence"] };
    if (/dry run|queued/.test(token)) return { key: "dry-run", ...CANONICAL_STATUS_LANGUAGE["dry-run"] };
    if (/read only|public safe|backend derived/.test(token)) return { key: "read-only", ...CANONICAL_STATUS_LANGUAGE["read-only"] };
    if (/live capital disabled|live capital off/.test(token)) return { key: "live-capital-off", ...CANONICAL_STATUS_LANGUAGE["live-capital-off"] };
    if (/paper/.test(token)) return { key: "paper-only", ...CANONICAL_STATUS_LANGUAGE["paper-only"] };
    if (/local only/.test(token)) return { key: "local-only", ...CANONICAL_STATUS_LANGUAGE["local-only"] };
    if (/non executable|research only|context only|prior only|challenge only/.test(token)) return { key: "non-executable", ...CANONICAL_STATUS_LANGUAGE["non-executable"] };
    if (/online|ok|ready|connected|available|active|configured|validated|certified|approved|passed|complete|written/.test(token)) return { key: "current", ...CANONICAL_STATUS_LANGUAGE.current };
    return {
        key: "raw-status",
        label: dashboardText(value, options.fallback || "Not exported"),
        tone: "pending",
        description: "Raw status value not yet mapped to the canonical dashboard language."
    };
}

function canonicalStatusLabel(value, options = {}) {
    const record = canonicalStatusRecord(value, options);
    return record ? record.label : dashboardText(value, options.fallback || "Not exported");
}

function canonicalStatusTone(value, fallback = "pending") {
    return canonicalStatusRecord(value, { fallback })?.tone || fallback;
}

function canonicalBadgeText(value) {
    return canonicalStatusRecord(value, { strict: true })?.label || dashboardText(value);
}

function htmlText(value, fallback = "Not connected yet") {
    return dashboardText(value, fallback).replace(/[&<>"']/g, (char) => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#39;"
    })[char]);
}

function publicOverviewText(value, fallback = "Not connected yet") {
    return dashboardText(value, fallback)
        .replace(/\bQ5E\b/g, "paper-lifecycle")
        .replace(/\bQ5\b/g, "paper-trading")
        .replace(/\bQ4\b/g, "strategy-review")
        .replace(/\bQ6\b/g, "learning-loop")
        .replace(/\bQ7\b/g, "proof-run")
        .replace(/\bPhase 4\b/g, "strategy review")
        .replace(/\bPhase 5\b/g, "paper-trading layer")
        .replace(/\bPhase 6\b/g, "learning loop")
        .replace(/\bPhase 7\b/g, "proof run")
        .replace(/\bPaperOps\b/g, "paper-trading runner")
        .replace(/\bQSASE\b/g, "public evidence dashboard")
        .replace(/idempotency_guard_holding_duplicate_or_already_submitted_setup/gi, "duplicate-protection check is holding a setup that already appears submitted")
        .replace(/\bresearch goals\b/gi, "research observations");
}

function overviewHtmlText(value, fallback = "Not connected yet") {
    return htmlText(publicOverviewText(value, fallback), fallback);
}

function literalHtmlText(value, fallback = "Not connected yet") {
    if (value === null || value === undefined || value === "") return fallback;
    return String(value).replace(/[&<>"']/g, (char) => ({
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#39;"
    })[char]);
}

function asArray(value) {
    return Array.isArray(value) ? value : [];
}

function statusClass(status) {
    const canonicalTone = canonicalStatusTone(status, status);
    return dashboardText(canonicalTone, "pending")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "") || "pending";
}

function normaliseCurrencyCode(value, fallback = "GBP") {
    const code = String(value || fallback || "GBP").trim().toUpperCase();
    return /^[A-Z]{3}$/.test(code) ? code : fallback;
}

function formatMoney(value, currency = "GBP") {
    const amount = Number(value || 0);
    return new Intl.NumberFormat("en-GB", {
        style: "currency",
        currency: normaliseCurrencyCode(currency),
        maximumFractionDigits: 0
    }).format(amount);
}

function capitalCurrency(capital = {}) {
    return normaliseCurrencyCode(capital.display_currency || capital.account_currency || "GBP");
}

function formatCapitalMoney(value, capital = {}) {
    return formatMoney(value, capitalCurrency(capital));
}

function formatUsd(value) {
    const amount = Number(value || 0);
    return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: "USD",
        maximumFractionDigits: 0
    }).format(amount);
}

function formatTime(value) {
    if (!value) return "Not connected";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "Unknown";
    return new Intl.DateTimeFormat("en-GB", {
        day: "2-digit",
        month: "short",
        hour: "2-digit",
        minute: "2-digit"
    }).format(date);
}

function formatDate(value) {
    if (!value) return "Current period";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "Current period";
    return new Intl.DateTimeFormat("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric"
    }).format(date);
}

function formatLatency(value) {
    if (value === null || value === undefined || value === "") return "unknown";
    const latency = Number(value);
    if (Number.isNaN(latency)) return dashboardText(value, "unknown");
    return `${Math.round(latency)} ms`;
}

function countBy(items, key) {
    return asArray(items).reduce((acc, item) => {
        const value = item?.[key] || "unknown";
        acc[value] = (acc[value] || 0) + 1;
        return acc;
    }, {});
}

function sourceIsCore(source = {}) {
    return DASHBOARD_CORE_SOURCE_KEYS.has(String(source.source_key || ""));
}

function sourceUsableForResearch(source = {}) {
    return Boolean(source.usable_for_research_context);
}

function sourceEligibleForSignalReview(source = {}) {
    return Boolean(source.eligible_for_signal_review ?? source.can_influence_signals);
}

function sourceCanAuthorizeOrders(source = {}) {
    return Boolean(source.can_authorize_orders);
}

function sourceDisplayStatus(source = {}) {
    const rawStatus = normalizeCanonicalStatusToken(source.status || "");
    const readiness = normalizeCanonicalStatusToken(source.readiness || "");
    const credentialStatus = normalizeCanonicalStatusToken(source.credential_status || "");
    const actionCategory = normalizeCanonicalStatusToken(source.action_category || "");
    if (rawStatus === "online") return "ok";
    if (rawStatus === "local only") return "local only";
    if (actionCategory === "intentionally disabled" || actionCategory === "needs adapter" || actionCategory === "provider decision required") {
        return "optional";
    }
    if (actionCategory === "local bridge required") return "local only";
    if (actionCategory === "needs credentials") return "not configured";
    if (!sourceIsCore(source)) {
        return "optional";
    }
    if (credentialStatus === "missing" || readiness.includes("credential required")) {
        return "not configured";
    }
    if (rawStatus === "degraded") return "degraded";
    if (rawStatus === "pending") return "waiting";
    return source.status || "waiting";
}

function sourceRequiresAction(source = {}) {
    const displayStatus = canonicalStatusRecord(sourceDisplayStatus(source));
    return displayStatus?.tone === "degraded" || displayStatus?.tone === "blocked";
}

function setText(selector, value) {
    const target = dashboardQuery(selector);
    if (target) target.textContent = value;
}

function renderStatusPill(status) {
    const record = canonicalStatusRecord(status);
    return `<b class="node-status ${statusClass(record.tone)}" title="${htmlText(record.description)}">${htmlText(record.label)}</b>`;
}

function renderMetric(label, value) {
    return `<div class="metric"><span>${htmlText(label)}</span><strong>${htmlText(value)}</strong></div>`;
}

function renderInlineBadge(value, status = "pending") {
    return `<span class="inline-badge ${statusClass(status)}">${htmlText(canonicalBadgeText(value))}</span>`;
}

function renderPanelBrief({ id, question, state, tone = "pending", primary, secondary, boundary }) {
    return `
        <section class="panel-brief ${statusClass(tone)}" data-panel-brief="${htmlText(id)}">
            <div class="panel-brief-main">
                <p class="label">Panel readout</p>
                <h3>${htmlText(question)}</h3>
                <p>${htmlText(primary)}</p>
            </div>
            <dl class="panel-brief-facts">
                <div>
                    <dt>State</dt>
                    <dd>${renderInlineBadge(state, tone)}</dd>
                </div>
                <div>
                    <dt>Watch</dt>
                    <dd>${htmlText(secondary)}</dd>
                </div>
                <div>
                    <dt>Boundary</dt>
                    <dd>${htmlText(boundary)}</dd>
                </div>
            </dl>
        </section>
    `;
}

function replacePanelBrief(id, config) {
    const target = dashboardQuery(`[data-panel-brief="${id}"]`);
    if (target) target.outerHTML = renderPanelBrief({ id, ...config });
}

function renderTagList(items, emptyText = "None recorded") {
    const list = Array.isArray(items) ? items.filter(Boolean) : [];
    if (!list.length) return `<span>${htmlText(emptyText)}</span>`;
    return list.map((item) => `<span>${htmlText(item)}</span>`).join("");
}

function sumNestedItems(items, key) {
    return asArray(items).reduce((total, item) => total + asArray(item?.[key]).length, 0);
}

function compactUnique(items, limit = 12) {
    const seen = new Set();
    const values = [];
    asArray(items).forEach((item) => {
        const value = dashboardText(item, "").trim();
        if (!value || seen.has(value)) return;
        seen.add(value);
        values.push(value);
    });
    return values.slice(0, limit);
}

function formatConfidence(value) {
    if (value === null || value === undefined || value === "") return "unknown";
    const score = Number(value);
    if (Number.isNaN(score)) return dashboardText(value, "unknown");
    return score <= 1 ? `${Math.round(score * 100)}%` : `${Math.round(score)}%`;
}

function formatProbability(value) {
    if (value === null || value === undefined || value === "") return "unknown";
    const score = Number(value);
    if (Number.isNaN(score)) return dashboardText(value, "unknown");
    return score <= 1 ? `${Math.round(score * 100)}%` : `${Math.round(score)}%`;
}

function formatPercent(value) {
    if (value === null || value === undefined || value === "") return "0%";
    const score = Number(value);
    if (Number.isNaN(score)) return dashboardText(value, "0%");
    return `${score}%`;
}

function findModule(status, key) {
    return asArray(status.modules).find((module) => module.key === key);
}

