function paperChartPointTimeMs(point = {}) {
    return qsaseTimestampMs(point.timestamp || point.observed_at || point.generated_at || point.date || point.time);
}

function paperChartTimeScale(points = [], left = 0, plotWidth = 0) {
    const timeValues = points.map(paperChartPointTimeMs).filter((value) => value !== null);
    const timeMin = timeValues.length ? Math.min(...timeValues) : null;
    const timeMax = timeValues.length ? Math.max(...timeValues) : null;
    const hasTimeScale = timeMin !== null && timeMax !== null && timeMax > timeMin;
    const xFor = (point, index) => {
        const pointMs = paperChartPointTimeMs(point);
        if (hasTimeScale && pointMs !== null) return left + ((pointMs - timeMin) / (timeMax - timeMin)) * plotWidth;
        return left + (points.length <= 1 ? plotWidth / 2 : (index / (points.length - 1)) * plotWidth);
    };
    const tickCount = Math.min(5, Math.max(1, hasTimeScale ? points.length : timeValues.length));
    const ticks = Array.from({ length: tickCount }, (_, index) => {
        const ratio = tickCount <= 1 ? 0.5 : index / (tickCount - 1);
        const tickMs = hasTimeScale
            ? timeMin + ((timeMax - timeMin) * ratio)
            : (timeValues[index] || timeValues[0] || null);
        return {
            x: hasTimeScale ? left + ratio * plotWidth : left + plotWidth / 2,
            anchor: index === 0 ? "start" : (index === tickCount - 1 ? "end" : "middle"),
            label: tickMs === null ? "Time pending" : formatTime(new Date(tickMs).toISOString())
        };
    });
    return { hasTimeScale, xFor, ticks };
}

function renderPaperChartTimeAxis(timeScale = {}, height = 0) {
    return `
        <g data-paper-chart-time-axis>
            ${asArray(timeScale.ticks).map((tick) => `
                <g class="chart-time-tick">
                    <line x1="${tick.x.toFixed(2)}" y1="${height - 28}" x2="${tick.x.toFixed(2)}" y2="${height - 22}"></line>
                    <text class="chart-axis-label chart-axis-time" x="${tick.x.toFixed(2)}" y="${height - 8}" text-anchor="${tick.anchor}">${literalHtmlText(tick.label)}</text>
                </g>
            `).join("")}
        </g>
    `;
}

function renderOverviewCapacityChart(capacity = {}) {
    const chartPoints = asArray(capacity.equity_curve).length
        ? asArray(capacity.equity_curve)
        : paperAccountEquityPoints({
            current_balance_gbp: capacity.equity_gbp,
            equity_gbp: capacity.equity_gbp,
            observed_at: capacity.observed_at,
            drawdown_pct: capacity.drawdown_pct
        });
    const stats = paperAccountEquityStats(chartPoints);
    const width = 520;
    const height = 150;
    const left = 66;
    const right = 16;
    const top = 18;
    const bottom = 28;
    const plotWidth = width - left - right;
    const plotHeight = height - top - bottom;
    const rawMin = stats.min;
    const rawMax = stats.max;
    const range = rawMax - rawMin;
    const padding = range > 0 ? range * 0.18 : Math.max(10, Math.abs(rawMax || 1000) * 0.01);
    const min = rawMin - padding;
    const max = rawMax + padding;
    const yFor = (value) => top + ((max - value) / (max - min || 1)) * plotHeight;
    const timeScale = paperChartTimeScale(chartPoints, left, plotWidth);
    const path = chartPoints
        .map((point, index) => `${index ? "L" : "M"} ${timeScale.xFor(point, index).toFixed(2)} ${yFor(point.equity_gbp).toFixed(2)}`)
        .join(" ");
    const usedWidth = Math.round(Math.min(1, Math.max(0, Number(capacity.used_fraction || 0))) * 100);
    const targetWidth = Math.round(Math.min(1, Math.max(0, Number(capacity.target_progress_fraction || 0))) * 100);

    return `
        <div class="overview-capacity-chart-card ${statusClass(capacity.tone || "online")}">
            <svg class="overview-capacity-line" viewBox="0 0 ${width} ${height}" role="img" aria-label="Paper account capacity over time" preserveAspectRatio="none" data-paper-capacity-line data-time-scaled-axis="${timeScale.hasTimeScale ? "true" : "false"}">
                <line class="chart-grid-line" x1="${left}" y1="${height - bottom}" x2="${width - right}" y2="${height - bottom}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(stats.max).toFixed(2)}" x2="${width - right}" y2="${yFor(stats.max).toFixed(2)}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(stats.min).toFixed(2)}" x2="${width - right}" y2="${yFor(stats.min).toFixed(2)}"></line>
                <path class="paper-equity-line" d="${path}"></path>
                <text class="chart-axis-label" x="4" y="${yFor(stats.max).toFixed(2)}">${literalHtmlText(formatMoney(stats.max))}</text>
                <text class="chart-axis-label" x="4" y="${yFor(stats.min).toFixed(2)}">${literalHtmlText(formatMoney(stats.min))}</text>
                ${renderPaperChartTimeAxis(timeScale, height)}
            </svg>
            <div class="overview-capacity-bar" aria-label="Paper capacity deployed">
                <span style="width: ${usedWidth}%"></span>
            </div>
            <div class="overview-capacity-bar target" aria-label="Paper growth target progress">
                <span style="width: ${targetWidth}%"></span>
            </div>
            <div class="overview-capacity-summary">
                ${renderMetric("Deployed", formatMoney(capacity.deployed_gbp))}
                ${renderMetric("Start", formatMoney(capacity.total_gbp))}
                ${renderMetric("Equity", formatMoney(capacity.equity_gbp))}
                ${renderMetric("Target", formatMoney(capacity.target_gbp))}
                ${renderMetric("P&L", formatMoney(capacity.total_pnl_gbp))}
            </div>
        </div>
    `;
}

function portfolioTradeRecordReason(record = {}, type = "order") {
    const explicitReason = record.why || record.reason || record.summary || record.evidence_summary || record.catalyst || record.close_reason;
    if (explicitReason) return overviewPlainText(explicitReason);
    const status = String(record.status || record.order_status || "").toLowerCase();
    const direction = String(record.direction || record.side || "").toLowerCase();
    if (type === "position") {
        return "Open paper position mirrored from Alpaca and tracked against current account value.";
    }
    if (direction === "sell") {
        return status.includes("fill")
            ? "Sell or close order completed in the paper account."
            : "Sell or close order is visible in the paper-account order history.";
    }
    if (status.includes("fill")) {
        return "Buy order completed in the paper account and added to the paper ledger.";
    }
    if (status === "new" || status === "accepted" || status === "pending_new") {
        return "Paper order is waiting for broker completion or cancellation.";
    }
    if (record.source_intent_id || record.intent_id) {
        return `Linked to ${record.source_intent_id || record.intent_id}.`;
    }
    return "Mirrored from the Alpaca paper account; no separate strategy note was exported for this row.";
}

function portfolioTradeTime(record = {}) {
    return record.filled_at || record.submitted_at || record.created_at || record.opened_at || record.observed_at || record.updated_at;
}

function portfolioTradePrice(record = {}) {
    const value = firstPresent(record.filled_avg_price, record.current_price, record.entry_price, record.limit_price, record.stop_price);
    if (value === null || value === undefined || value === "") return "market";
    const number = Number(value);
    return Number.isFinite(number) ? number.toLocaleString("en-GB", { maximumFractionDigits: 2 }) : dashboardText(value);
}

function renderPortfolioTradeTimelineRow(record = {}, type = "order") {
    const symbol = record.symbol || record.instrument || record.asset || record.ticker || "Instrument";
    const direction = dashboardText(record.direction || record.side || (type === "position" ? "long" : "order"));
    const status = dashboardText(record.status || record.order_status || (type === "position" ? "open position" : "recorded"));
    const quantity = firstPresent(record.quantity, record.qty, record.filled_quantity, record.shares, record.position_qty, "n/a");
    return `
        <li class="portfolio-trade-row ${statusClass(status)}">
            <div>
                <strong>${htmlText(symbol)}</strong>
                <span>${htmlText(direction)} · ${htmlText(status)} · ${htmlText(formatTime(portfolioTradeTime(record)))}</span>
            </div>
            <dl>
                <div><dt>Qty</dt><dd>${htmlText(quantity)}</dd></div>
                <div><dt>Price</dt><dd>${htmlText(portfolioTradePrice(record))}</dd></div>
                <div><dt>Why</dt><dd>${htmlText(portfolioTradeRecordReason(record, type))}</dd></div>
            </dl>
        </li>
    `;
}

function renderPortfolioTradeTimeline(portfolio = {}) {
    const orders = asArray(portfolio.orders);
    const positions = asArray(portfolio.open_positions).map((position) => ({
        ...position,
        direction: position.direction || position.side || "long",
        status: position.status || "open position"
    }));
    const buyRecords = [
        ...orders.filter((order) => /buy|long/i.test(String(order.direction || order.side || ""))),
        ...positions.filter((position) => !/short|sell/i.test(String(position.direction || position.side || "")))
    ].slice(0, 80);
    const sellRecords = orders
        .filter((order) => /sell|close|short/i.test(String(order.direction || order.side || "")))
        .slice(0, 80);
    const renderEmpty = (message) => `<li class="portfolio-trade-row empty"><span>${htmlText(message)}</span></li>`;
    return `
        <details class="portfolio-trade-timeline" data-portfolio-trade-timeline>
            <summary>
                <span>Trade timeline</span>
                <strong>${buyRecords.length} bought or held · ${sellRecords.length} sold or closed</strong>
                <em>Expand trade history</em>
            </summary>
            <div class="portfolio-trade-timeline-grid">
                <section>
                    <h4>Bought and held</h4>
                    <ul class="portfolio-trade-list">
                        ${buyRecords.length ? buyRecords.map((record) => renderPortfolioTradeTimelineRow(record, positions.includes(record) ? "position" : "order")).join("") : renderEmpty("No buy or open-position rows exported in this snapshot.")}
                    </ul>
                </section>
                <section>
                    <h4>Sold and closed</h4>
                    <ul class="portfolio-trade-list">
                        ${sellRecords.length ? sellRecords.map((record) => renderPortfolioTradeTimelineRow(record, "order")).join("") : renderEmpty("No sell or close rows exported in this snapshot.")}
                    </ul>
                </section>
            </div>
        </details>
    `;
}

