function renderQsaseGuideMarker(key, override = {}) {
    const guide = { ...(QSASE_GUIDE_MARKERS[key] || {}), ...(override || {}) };
    if (!guide.title && !guide.summary) return "";
    const tooltipId = `qsase-guide-${String(key || guide.title || "marker").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`;
    const rows = asArray(guide.rows);
    return `
        <div class="info-hover qsase-guide-marker" data-guide-marker="${literalHtmlText(key || "guide")}">
            <button class="info-button" type="button" aria-label="${literalHtmlText(`Guide: ${guide.title || "What this means"}`)}" aria-describedby="${literalHtmlText(tooltipId)}">i</button>
            <div id="${literalHtmlText(tooltipId)}" class="info-card section-explainer qsase-guide-card" role="tooltip" data-section-explainer="${literalHtmlText(key || "guide")}" data-tooltip-contract="nontechnical-guide">
                <strong>${qsaseHtmlText(guide.title || "What this means")}</strong>
                ${guide.summary ? `<p>${qsaseHtmlText(guide.summary)}</p>` : ""}
                ${rows.length ? `
                    <dl class="explainer-grid compact">
                        ${rows.map(([term, meaning]) => `
                            <div>
                                <dt>${qsaseHtmlText(term)}</dt>
                                <dd>${qsaseHtmlText(meaning)}</dd>
                            </div>
                        `).join("")}
                    </dl>
                ` : ""}
            </div>
        </div>
    `;
}

function qsaseRouterDecisionCounts(router = {}) {
    const ranked = asArray(router.scoreboard?.ranked_decisions);
    const outputCounts = ranked.reduce((counts, decision) => {
        const output = decision.router_output || "unknown";
        counts[output] = (counts[output] || 0) + 1;
        return counts;
    }, {});
    return {
        held: firstPresent(router.hold_count, outputCounts.hold_missing_evidence, outputCounts.hold, outputCounts.watchlist, 0),
        safetyBlocks: firstPresent(router.blocked_safety_boundary_count, outputCounts.blocked_safety_boundary, 0),
        paperReview: firstPresent(router.paper_review_candidate_count, outputCounts.paper_review_candidate, 0),
        ranked: firstPresent(router.decision_count, router.scoreboard?.ranked_count, ranked.length, 0)
    };
}

function qsaseRouterHeadline(router = {}, gate = {}) {
    const why = router.why_not_trading_now || {};
    const rawReason = why.reason || router.scoreboard?.top_reason || gate.top_blocking_gate || "No current router decision exported.";
    if (/akber_filter_artifact_degraded/i.test(String(rawReason || ""))) {
        const counts = qsaseRouterDecisionCounts(router);
        return `${counts.held} held: Akber confirmation evidence is incomplete; ${counts.paperReview} passed; ${counts.safetyBlocks} vetoed.`;
    }
    return qsaseHumanText(rawReason);
}

function renderQsaseSectionHeader(label, headline, meta = "", tone = "pending", guideKey = "") {
    return `
        <div class="qsase-section-head">
            <div>
                <span>${qsaseHtmlText(label)}</span>
                <strong>${qsaseHtmlText(headline)}</strong>
            </div>
            <div class="qsase-section-actions">
                ${meta ? renderQsaseInlineBadge(meta, tone) : ""}
                ${guideKey ? renderQsaseGuideMarker(guideKey) : ""}
            </div>
        </div>
    `;
}

function renderQsasePortfolioValue(qsase = {}, analyticsModel = null) {
    const portfolio = qsase.dashboard_portfolio || {};
    const model = analyticsModel || qsasePortfolioAnalyticsModel(qsase);
    const emptyPortfolio = model.emptyPortfolio;
    const section = qsase.portfolio_value || {};
    const history = qsase.trading_history || {};
    const contractSeries = asArray(portfolio.equity_curve);
    const sectionSeries = asArray(section.series);
    const series = contractSeries.length ? contractSeries : sectionSeries;
    const latest = portfolio.latest_curve_point || series.at(-1) || {};
    const first = series[0] || latest;
    const currency = normaliseCurrencyCode(portfolio.display_currency || latest.display_currency || first.display_currency || "GBP");
    const latestValue = modelNumber(portfolio.current_value_gbp ?? qsaseSeriesValue(latest), 0);
    const firstValue = series.length ? modelNumber(qsaseSeriesValue(first), latestValue) : latestValue;
    const rawDelta = latestValue - firstValue;
    const delta = Math.abs(rawDelta) < 0.5 ? 0 : rawDelta;
    const deltaPct = firstValue ? (delta / firstValue) * 100 : 0;
    const deltaPctLabel = `${delta > 0 ? "+" : ""}${deltaPct.toFixed(2)}%`;
    const deltaMoneyLabel = `${delta > 0 ? "+" : ""}${formatMoney(delta, currency)}`;
    const chartSeries = series.length
        ? series
        : [{ ...latest, portfolio_value: latestValue, timestamp: portfolio.generated_at || qsase.generated_at }];
    const periodStart = first.timestamp || first.observed_at || first.generated_at || portfolio.generated_at || qsase.generated_at;
    const periodLabel = periodStart ? `From ${formatDate(periodStart)}` : "Current period";
    const width = 920;
    const height = emptyPortfolio ? 170 : 260;
    const left = 74;
    const right = 26;
    const top = 26;
    const bottom = 34;
    const values = chartSeries.map((point) => modelNumber(point.portfolio_value ?? point.equity_gbp ?? point.current_value_gbp ?? qsaseSeriesValue(point), latestValue));
    const minRaw = values.length ? Math.min(...values) : 0;
    const maxRaw = values.length ? Math.max(...values) : 1;
    const padding = Math.max((maxRaw - minRaw) * 0.16, Math.abs(maxRaw || 1) * 0.005, 1);
    const min = minRaw - padding;
    const max = maxRaw + padding;
    const plotWidth = width - left - right;
    const plotHeight = height - top - bottom;
    const yFor = (value) => top + ((max - value) / (max - min || 1)) * plotHeight;
    const pointTimeMs = (point) => qsaseTimestampMs(point.timestamp || point.observed_at || point.generated_at);
    const timeValues = chartSeries.map(pointTimeMs).filter((value) => value !== null);
    const timeMin = timeValues.length ? Math.min(...timeValues) : 0;
    const timeMax = timeValues.length ? Math.max(...timeValues) : 0;
    const hasTimeScale = timeValues.length > 1 && timeMax > timeMin;
    const xForPoint = (point, index) => {
        const pointMs = pointTimeMs(point);
        if (hasTimeScale && pointMs !== null) {
            return left + ((pointMs - timeMin) / (timeMax - timeMin || 1)) * plotWidth;
        }
        return left + (chartSeries.length <= 1 ? plotWidth / 2 : (index / (chartSeries.length - 1)) * plotWidth);
    };
    const tickCount = hasTimeScale ? Math.min(5, Math.max(2, chartSeries.length)) : 0;
    const timeTicks = Array.from({ length: tickCount }, (_, index) => {
        const ratio = tickCount <= 1 ? 0 : index / (tickCount - 1);
        const ms = timeMin + ((timeMax - timeMin) * ratio);
        return {
            anchor: index === 0 ? "start" : (index === tickCount - 1 ? "end" : "middle"),
            label: formatTime(new Date(ms).toISOString()),
            x: left + (plotWidth * ratio)
        };
    });
    const timeAxis = timeTicks.map((tick) => `
        <g class="chart-time-tick">
            <line x1="${tick.x.toFixed(2)}" y1="${height - bottom}" x2="${tick.x.toFixed(2)}" y2="${height - bottom + 7}"></line>
            <text class="chart-axis-label chart-axis-time" x="${tick.x.toFixed(2)}" y="${height - 8}" text-anchor="${tick.anchor}">${literalHtmlText(tick.label)}</text>
        </g>
    `).join("");
    const linePath = chartSeries.map((point, index) => `${index ? "L" : "M"} ${xForPoint(point, index).toFixed(2)} ${yFor(modelNumber(point.portfolio_value ?? point.equity_gbp ?? point.current_value_gbp ?? qsaseSeriesValue(point), latestValue)).toFixed(2)}`).join(" ");
    const maxAxisLabel = formatMoney(maxRaw, currency);
    const minAxisLabel = formatMoney(minRaw, currency);
    const valueAxisLabels = maxAxisLabel === minAxisLabel
        ? ""
        : `
            <text class="chart-axis-label" x="4" y="${yFor(maxRaw).toFixed(2)}">${literalHtmlText(maxAxisLabel)}</text>
            <text class="chart-axis-label" x="4" y="${yFor(minRaw).toFixed(2)}">${literalHtmlText(minAxisLabel)}</text>
        `;
    const tradeRows = asArray(history.rows).slice(0, 18);
    const markers = tradeRows.map((row) => {
        const markerPoint = qsaseNearestSeriesPoint(chartSeries, row.closed_at || row.opened_at || row.submitted_at);
        const index = Math.max(0, chartSeries.indexOf(markerPoint));
        if (!chartSeries.length) return "";
        const markerValue = modelNumber(markerPoint.portfolio_value ?? markerPoint.equity_gbp ?? markerPoint.current_value_gbp ?? qsaseSeriesValue(markerPoint), latestValue);
        return `
            <g class="qsase-trade-marker ${statusClass(row.row_type || row.postmortem_status || "pending")}">
                <circle cx="${xForPoint(markerPoint, index).toFixed(2)}" cy="${yFor(markerValue).toFixed(2)}" r="4.5"></circle>
                <title>${literalHtmlText(`${row.instrument || "trade"} · ${row.row_type || "history"} · ${formatTime(row.closed_at || row.opened_at || row.submitted_at)}`)}</title>
            </g>
        `;
    }).join("");
    const tone = delta > 0 ? "online" : (delta < 0 ? "blocked" : "pending");
    return `
        <section id="qsase-portfolio" class="qsase-section qsase-portfolio-value ${emptyPortfolio ? "is-empty" : ""} ${statusClass(tone)}" data-qsase-section="portfolio_value_return">
            <header class="qsase-portfolio-band-head">
                <div>
                    <h2>Performance</h2>
                </div>
                <div class="qsase-performance-outcome ${tone}">
                    <strong>${deltaPctLabel}</strong>
                    <span>${deltaMoneyLabel} · ${chartSeries.length} account snapshot${chartSeries.length === 1 ? "" : "s"}</span>
                </div>
                ${renderQsaseGuideMarker("portfolio_value_return")}
            </header>
            <svg class="qsase-portfolio-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Qadam paper portfolio performance ${literalHtmlText(periodLabel.toLowerCase())} with timestamped horizontal axis" preserveAspectRatio="none" data-qsase-portfolio-line data-time-scaled-axis="${hasTimeScale ? "true" : "false"}">
                <line class="chart-grid-line" x1="${left}" y1="${height - bottom}" x2="${width - right}" y2="${height - bottom}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(maxRaw).toFixed(2)}" x2="${width - right}" y2="${yFor(maxRaw).toFixed(2)}"></line>
                <line class="chart-grid-line muted" x1="${left}" y1="${yFor(minRaw).toFixed(2)}" x2="${width - right}" y2="${yFor(minRaw).toFixed(2)}"></line>
                <path class="paper-equity-line ${statusClass(tone)}" d="${linePath}"></path>
                ${markers}
                <g data-qsase-time-axis>
                    ${timeAxis}
                </g>
                ${valueAxisLabels}
            </svg>
        </section>
    `;
}

function qsaseTimestamp(row = {}) {
    return row.closed_at || row.filled_at || row.submitted_at || row.opened_at || row.generated_at || row.observed_at;
}

function qsaseTradeEventTone(row = {}) {
    const event = String(row.event_type || row.row_type || row.status || "").toLowerCase();
    if (event.includes("sell") || event.includes("close") || event.includes("closed")) return "sell";
    if (event.includes("buy") || event.includes("order") || event.includes("submitted")) return "buy";
    return statusClass(row.status || row.row_type || "pending");
}

function qsaseTradeEventDescription(row = {}) {
    const raw = firstPresent(row.reason, row.postmortem_status, row.boundary, "Read-only paper ledger record.");
    return qsaseHumanText(raw, "Read-only paper ledger record.")
        .replace(/postmortem due/gi, "Needs a post-trade note explaining what happened and what Qadam learned.")
        .replace(/mirrored order only no create cancel replace or close/gi, "Mirrored from Alpaca for visibility only; this dashboard did not create, cancel, replace, or close it.")
        .replace(/proof credit/gi, "a fully documented paper result");
}

function qsaseTradeQuantity(row = {}, rows = []) {
    const explicit = firstPresent(row.filled_quantity, row.quantity, row.qty, row.shares, row.position_qty, row.filled_qty);
    if (explicit !== undefined && explicit !== null && explicit !== "") return explicit;
    const id = row.order_id || row.trade_id;
    if (!id) return null;
    const match = asArray(rows).find((candidate) => candidate !== row && (candidate.order_id === id || candidate.trade_id === id) && firstPresent(candidate.filled_quantity, candidate.quantity, candidate.qty, candidate.shares, candidate.position_qty, candidate.filled_qty) !== undefined);
    return match ? firstPresent(match.filled_quantity, match.quantity, match.qty, match.shares, match.position_qty, match.filled_qty) : null;
}

function qsaseFormatQuantity(value) {
    const number = Number(value);
    if (Number.isFinite(number)) return Number.isInteger(number) ? String(number) : number.toFixed(4).replace(/0+$/g, "").replace(/\.$/, "");
    return value === undefined || value === null || value === "" ? "amount not exported" : String(value);
}

function qsaseTradeAmountLabel(row = {}, rows = []) {
    const quantity = qsaseTradeQuantity(row, rows);
    const formattedQuantity = qsaseFormatQuantity(quantity);
    if (formattedQuantity === "amount not exported") return formattedQuantity;
    const unit = Number(formattedQuantity) === 1 ? "unit" : "units";
    const tone = qsaseTradeEventTone(row);
    const verb = tone === "sell" ? "Sold / closed" : tone === "buy" ? "Bought / ordered" : "Amount";
    return `${verb} ${formattedQuantity} ${unit}`;
}

function qsaseTradeActionLabel(row = {}) {
    const tone = qsaseTradeEventTone(row);
    if (tone === "sell") return "sell or close";
    if (tone === "buy") return "buy or order";
    return qsaseHumanText(row.event_label || row.row_type || row.status, "recorded event").toLowerCase();
}

function qsaseClosedTradesInWindow(rows = [], days = 7) {
    const closedRows = asArray(rows).filter((row) => row.closed_at || String(row.row_type || "").includes("closed_paper_trade"));
    const timestamps = closedRows
        .map((row) => Date.parse(qsaseTimestamp(row)))
        .filter(Number.isFinite);
    const latest = timestamps.length ? Math.max(...timestamps) : Date.now();
    const threshold = latest - days * 24 * 60 * 60 * 1000;
    return closedRows.filter((row) => {
        const timestamp = Date.parse(qsaseTimestamp(row));
        return Number.isFinite(timestamp) && timestamp >= threshold;
    }).length;
}

function qsaseTradingHistoryNarrative(section = {}, lifecycle = {}, proof = {}, rows = []) {
    const recentRows = asArray(rows).slice(0, 8);
    const latest = recentRows[0] || {};
    const recentInstruments = Array.from(new Set(recentRows.map((row) => row.instrument).filter(Boolean))).slice(0, 5);
    const buyOrOrderCount = recentRows.filter((row) => qsaseTradeEventTone(row) === "buy").length;
    const sellOrCloseCount = recentRows.filter((row) => qsaseTradeEventTone(row) === "sell").length;
    const closedCount = modelNumber(section.closed_trade_row_count, 0);
    const orderMirrorCount = modelNumber(section.paper_order_mirror_row_count, 0);
    const closedLastSevenDays = qsaseClosedTradesInWindow(rows, 7);
    const latestInstrument = latest.instrument || "the latest paper record";
    const latestAction = latest.instrument ? qsaseTradeActionLabel(latest) : "recorded event";
    const latestTime = latest.instrument ? formatTime(qsaseTimestamp(latest)) : "time not exported";

    return {
        recordLabel: `${closedLastSevenDays} closed trades in the last 7 days`,
        recentHeadline: recentRows.length
            ? `Recent activity: ${recentInstruments.length ? recentInstruments.join(", ") : "symbols not exported"}`
            : "No recent paper activity exported",
        recentSummary: recentRows.length
            ? `The latest record is a ${latestAction} entry for ${latestInstrument} at ${latestTime}. Across the latest visible records, ${buyOrOrderCount} are buys or accepted orders and ${sellOrCloseCount} are sells or closes.`
            : "The paper ledger has not exported recent rows for this section.",
        totals: [
            ["Closed trades", closedCount],
            ["Mirrored orders", orderMirrorCount],
            ["Last 7 days", closedLastSevenDays]
        ]
    };
}

function renderQsaseTradingTimelineRows(rows = []) {
    const allRows = asArray(rows);
    if (!allRows.length) {
        return `<article class="qsase-record-card pending"><strong>No trading-history rows exported.</strong></article>`;
    }
    return allRows.map((row) => {
        const tone = qsaseTradeEventTone(row);
        return `
            <article class="qsase-trade-event ${tone}" role="listitem" data-qsase-trade-event>
                <div class="qsase-trade-event-time">
                    <span>${qsaseHtmlText(row.event_label || row.row_type || row.status, "Recorded event")}</span>
                    <strong>${formatTime(qsaseTimestamp(row))}</strong>
                </div>
                <div class="qsase-trade-event-main">
                    <strong>${qsaseHtmlText(row.instrument, "Instrument")}</strong>
                    <p>${qsaseHtmlText(qsaseTradeEventDescription(row))}</p>
                </div>
                <div class="qsase-trade-event-amount">
                    <span>Amount</span>
                    <strong>${qsaseHtmlText(qsaseTradeAmountLabel(row, allRows))}</strong>
                </div>
            </article>
        `;
    }).join("");
}

const QSASE_SOURCE_FAMILY_LABELS = {
    conflict: "Conflict & Geopolitics",
    macro: "Macro & Trade Data",
    market: "Markets & Technical Analysis",
    market_context_taxonomy: "Market Context Taxonomy",
    physical: "Physical World Signals",
    social: "Social News & Filings"
};

function qsaseFamilyLabel(value) {
    const key = String(value || "").trim().toLowerCase();
    return QSASE_SOURCE_FAMILY_LABELS[key] || qsaseHumanText(value, "Source category");
}

function qsaseSourceDescription(row = {}) {
    return row.description || "This read-only source category can strengthen or weaken a hypothesis, but it cannot create trades.";
}

